package main

import (
	"fmt"
	"runtime"
	"strings"
	"unsafe"

	uv "github.com/charmbracelet/ultraviolet"
	"github.com/charmbracelet/x/vt"
)

func heap() uint64 { runtime.GC(); var m runtime.MemStats; runtime.ReadMemStats(&m); return m.HeapAlloc }

func main() {
	fmt.Println("sizeof Cell", unsafe.Sizeof(uv.Cell{}))
	for _, cols := range []int{120, 200} {
		before := heap()
		e := vt.NewEmulator(cols, 50)
		go func() { buf := make([]byte, 4096); for { if _, err := e.Read(buf); err != nil { return } } }()
		line := "\x1b[38;5;245m" + strings.Repeat("─", cols) + "\x1b[0m\r\n"
		for i := 0; i < 12000; i++ { e.Write([]byte(line)) }
		after := heap()
		fmt.Printf("cols=%d scrollback=%d heap delta=%d MB\n", cols, e.ScrollbackLen(), (after-before)>>20)
		runtime.KeepAlive(e)
	}
}
EOF
