package main

import (
	"fmt"
	"runtime"
	"strings"

	"github.com/charmbracelet/x/vt"
)

func heap() uint64 { runtime.GC(); var m runtime.MemStats; runtime.ReadMemStats(&m); return m.HeapAlloc }

const cols = 290

func run(name string, mk func(i int) string) {
	before := heap()
	e := vt.NewEmulator(cols, 78)
	go func() { buf := make([]byte, 4096); for { if _, err := e.Read(buf); err != nil { return } } }()
	for i := 0; i < 10100; i++ { e.Write([]byte(mk(i) + "\r\n")) }
	cellMB := float64(heap()-before) / (1 << 20)
	sb := e.Scrollback()
	before = heap()
	strs := make([]string, sb.Len())
	for i := range strs { strs[i] = strings.Clone(sb.Line(i).Render()) }
	strMB := float64(heap()-before) / (1 << 20)
	fmt.Printf("%-28s cells(whole emulator) %6.1f MB   rendered strings %5.1f MB   %4.0fx\n", name, cellMB, strMB, cellMB/strMB)
	runtime.KeepAlive(e); runtime.KeepAlive(strs)
}

