func drain(e *vt.Emulator) { go func() { b := make([]byte, 4096); for { if _, err := e.Read(b); err != nil { return } } }() }

func main() {
	cases := map[string]string{
		"16/256/rgb fg+bg":     "\x1b[31mred\x1b[0m \x1b[38;5;208;48;5;17m256\x1b[0m \x1b[38;2;10;20;30;48;2;200;100;50mrgb\x1b[0m \x1b[91mbright\x1b[0m",
		"attrs":                "\x1b[1mb\x1b[22m \x1b[2md\x1b[22m \x1b[3mi\x1b[23m \x1b[5mbl\x1b[25m \x1b[7mrev\x1b[27m \x1b[8mhid\x1b[28m \x1b[9mstrike\x1b[29m",
		"underline styles+col": "\x1b[4mu\x1b[24m \x1b[4:3mcurly\x1b[4:0m \x1b[4:2;58;2;255;0;0mdbl-red\x1b[0m \x1b[4:4;58;5;33mdot\x1b[0m",
		"osc8 link w/ params":  "see \x1b]8;id=x1;https://example.com/a?b=c\x1b\\link text\x1b]8;;\x1b\\ after",
		"wide chars":           "中文字符 テスト 🙂👍 end",
		"graphemes":            "é 👨‍👩‍👧 🇺🇸 ✳️ done",
		"styled bg spaces":     "x\x1b[44m     \x1b[0m y \x1b[41m   \x1b[0m",
		"tab + gaps":           "a\tb\t\tc",
		"box drawing":          "\x1b[38;2;136;136;136m╭────╮│ ⎿ ●\x1b[0m",
	}
	for name, in := range cases {
		a := vt.NewEmulator(120, 3); drain(a)
		a.Write([]byte(in + "\r\n\n\n\n"))
		orig := a.Scrollback().Line(0)
		s := orig.Render()
		b := vt.NewEmulator(120, 3); drain(b)
		b.Write([]byte(s))
		var back uv.Line
		for x := 0; x < 120; x++ { c := b.CellAt(x, 0); if c == nil { back = append(back, uv.Cell{}) } else { back = append(back, *c) } }
		diffs := 0; first := ""
		for x := range orig {
			if !orig[x].Equal(&back[x]) {
				if diffs == 0 { first = fmt.Sprintf(" first@%d: %+v vs %+v", x, orig[x], back[x]) }
				diffs++
			}
		}
		fmt.Printf("%-22s cells=%3d diffs=%d%s\n", name, len(orig), diffs, first)
	}
}
EOF
